fn pairwise_addition(a: Vec<i32>) -> Vec<i32> {
    let len = a.len();
    assert!(
        len % 2 == 0,
        "Input vector length must be even, got length {}",
        len
    );

    let mut result = Vec::with_capacity(len / 2);
    for chunk in a.chunks(2) {
        // chunk is guaranteed to have length 2 because len is even
        result.push(chunk[0] + chunk[1]);
    }
    result
}

